export function compare(a, b) {
  const clean = (version) => version.split('+')[0].split('-')[0];
  const left = clean(a).split('.').map(Number);
  const right = clean(b).split('.').map(Number);
  for (let i = 0; i < 3; i += 1) {
    if (left[i] !== right[i]) return left[i] - right[i];
  }
  return 0;
}
